// Noise ring: writers still set S.noise; a value that differs from what the last decay left behind is a new noise and takes a slot.
// Repeats within 4 m merge (louder, longer); otherwise the quietest-remaining or expired slot is replaced.
fn hearRing34(dt:f32){
 let n=S.noise;
 if(n.z>0.0&&any(n!=S.noiseSeen34)){var slot=6u;var weakest=0u;
  for(var k=0u;k<6u;k++){let r=S.noiseRing34[k];if(slot==6u&&r.z>0.0&&distance(r.xy,n.xy)<4.0){slot=k;}if(r.z<S.noiseRing34[weakest].z){weakest=k;}}
  if(slot<6u){let r=S.noiseRing34[slot];S.noiseRing34[slot]=vec4f(n.xy,max(r.z,n.z),max(r.w,n.w));}else{S.noiseRing34[weakest]=n;}}
 for(var k=0u;k<6u;k++){S.noiseRing34[k].z=max(0.0,S.noiseRing34[k].z-dt);}
 S.noiseSeen34=vec4f(n.xy,max(0.0,n.z-dt),n.w);
}
